import{_ as t,o as n,c as i,a5 as o}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"3. Writing and Running Your First Program","description":"The Little Book of C — 3. Writing and Running Your First Program","frontmatter":{"title":"3. Writing and Running Your First Program","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Getting Started"],"description":"The Little Book of C — 3. Writing and Running Your First Program","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":3,"sidebarWeight":3,"lang":"en-US","alternateEn":"/posts/c教程/en-US/01-Getting Started/003-Writing and Running Your First Program","alternateZh":"/posts/c教程/zh-CN/01-入门/003-Writing and Running Your First Program"},"headers":[],"relativePath":"posts/c教程/en-US/01-Getting Started/003-Writing and Running Your First Program.md","filePath":"posts/c教程/en-US/01-Getting Started/003-Writing and Running Your First Program.md","lastUpdated":1790163617000}'),a={name:"posts/c教程/en-US/01-Getting Started/003-Writing and Running Your First Program.md"};function s(r,e,l,p,d,c){return n(),i("div",null,[...e[0]||(e[0]=[o(`<p>[中文版本](/posts/c教程/zh-CN/01-入门/003-Writing and Running Your First Program)</p><p>Now that your compiler is ready, it’s time to write your first real C program. This is where the magic happens, you’ll write plain text, compile it into machine instructions, and watch your computer follow your commands exactly.</p><p>C doesn’t hide what’s happening under the hood. Every step, writing, compiling, linking, running, is visible and under your control.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><p>Create a new file named<code>hello.c</code> and type this code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello, world!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Then, compile and run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span>
<span class="line"><span>./hello</span></span></code></pre></div><p>You should see:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello, world!</span></span></code></pre></div><h4 id="breaking-it-down" tabindex="-1">Breaking It Down <a class="header-anchor" href="#breaking-it-down" aria-label="Permalink to &quot;Breaking It Down&quot;">​</a></h4><p><code>#include &lt;stdio.h&gt;</code> This tells the compiler to use the Standard Input/Output library, which provides the<code>printf</code> function.</p><p><code>int main(void)</code> Every C program starts with a<code>main</code> function. It’s the entry point, where execution begins.</p><p><code>printf(&quot;Hello, world!\\n&quot;);</code> This prints text to the screen. The<code>\\n</code> means “newline,” so the next output starts on a new line.</p><p><code>return 0;</code> When<code>main</code> returns 0, it tells the operating system that your program finished successfully.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Your “Hello, world” may look simple, but it represents an entire process:</p><ol><li>The compiler translates your text (<code>hello.c</code>) into object code (<code>hello.o</code>).</li><li>The linker combines that code with standard libraries.</li><li>The executable (<code>hello</code>) is pure machine instructions.</li><li>The operating system loads and runs it.</li></ol><p>Understanding this flow is what makes C special, it’s not just about writing code, but about knowing how code becomes software.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Change the message to<code>&quot;Hello, C learner!&quot;</code> and recompile.</p><p>Add another line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;This is my first C program.\\n&quot;);</span></span></code></pre></div><p>Try leaving out the semicolon, what error does the compiler show?</p><p>Try removing<code>#include &lt;stdio.h&gt;</code>, what happens then?</p><p>Experiment and break things. Every error teaches you how C thinks.</p><p>You’ve just written and run your first C program, a direct conversation between you and the machine. From here, every new piece of code builds on this simple moment of control and understanding.</p>`,27)])])}const g=t(a,[["render",s]]);export{u as __pageData,g as default};
